// Набір безпечних read-only методів: показує, що реально доступно на порталі.
// Помилка по окремому методу — теж результат (значить нема scope або функціоналу).
const probes = [
  { method: 'profile', params: {}, why: 'від кого працює вебхук' },
  { method: 'scope', params: {}, why: 'які права видані вебхуку' },
  { method: 'catalog.catalog.list', params: {}, why: 'торгові каталоги (інфоблоки)' },
  { method: 'catalog.store.list', params: {}, why: 'склади; порожньо або помилка = складський облік вимкнений' },
  { method: 'catalog.measure.list', params: {}, why: 'одиниці виміру для мапінгу' },
  { method: 'catalog.priceType.list', params: {}, why: 'типи цін' },
  { method: 'crm.product.fields', params: {}, why: 'поля товару CRM, у т.ч. кастомні' },
  { method: 'crm.productsection.list', params: {}, why: 'розділи товарів CRM' },
  { method: 'crm.product.list', params: { select: ['ID', 'NAME', 'XML_ID', 'PROPERTY_*'], start: 0 }, why: 'скільки товарів уже є і чи заповнений XML_ID' }
];
return probes.map((p) => ({ json: p }));

// Зводимо відповіді в один звіт: що доступно, що ні, і ключові висновки.
const probes = $('Методи для перевірки').all();
const answers = $input.all();
const report = [];

for (let i = 0; i < answers.length; i++) {
  const probe = probes[i] ? probes[i].json : { method: `#${i}` , why: '' };
  const body = answers[i].json || {};
  const ok = body.error === undefined && body.error_description === undefined;
  report.push({
    method: probe.method,
    why: probe.why,
    ok,
    error: ok ? null : `${body.error || ''} ${body.error_description || ''}`.trim(),
    total: body.total !== undefined ? body.total : null,
    result: ok ? body.result : null
  });
}

const byMethod = Object.fromEntries(report.map((r) => [r.method, r]));
const stores = byMethod['catalog.store.list'];
const storeList = stores && stores.ok ? (stores.result.stores || stores.result || []) : [];
const products = byMethod['crm.product.list'];

const conclusions = {
  scopeGranted: byMethod['scope'] && byMethod['scope'].ok ? byMethod['scope'].result : 'не вдалося отримати',
  catalogAvailable: byMethod['catalog.catalog.list'] ? byMethod['catalog.catalog.list'].ok : false,
  inventoryManagement: Array.isArray(storeList) && storeList.length > 0
    ? `схоже, увімкнений: складів ${storeList.length}`
    : 'схоже, вимкнений або немає прав — залишки пишемо у QUANTITY товару',
  existingProducts: products && products.total !== null ? products.total : 'невідомо',
  nextStep: 'віддати цей вивід у чат — на його основі будується таблиця мапінгу'
};

return [{ json: { conclusions, report } }];
